// ========================================
// VALIDARE & ÎMBOGĂȚIRE TRANSCRIERE CU DIARIZATION
// ========================================

const items = $input.all();

for (const item of items) {
  // ===== EXTRAGE TEXT CU VORBITORI SEPARAȚI =====
  let text = '';
  let textWithSpeakers = '';
  let speakerCount = 0;
  let speakerSegments = [];

  // Dacă avem structura Deepgram cu diarization
  if (item.json.results?.channels?.[0]?.alternatives?.[0]) {
    const alternative = item.json.results.channels[0].alternatives[0];

    // Text simplu (fără vorbitori)
    text = alternative.transcript || '';

    // Dacă avem words cu speaker info, construim textul cu vorbitori
    if (alternative.words && alternative.words.length > 0) {
      let currentSpeaker = null;
      let currentText = '';

      alternative.words.forEach(word => {
        if (word.speaker !== currentSpeaker) {
          // Salvează segmentul anterior
          if (currentSpeaker !== null && currentText.trim()) {
            speakerSegments.push({
              speaker: currentSpeaker,
              text: currentText.trim()
            });
          }
          // Începe segment nou
          currentSpeaker = word.speaker;
          currentText = word.punctuated_word || word.word;
        } else {
          currentText += ' ' + (word.punctuated_word || word.word);
        }
      });

      // Salvează ultimul segment
      if (currentText.trim()) {
        speakerSegments.push({
          speaker: currentSpeaker,
          text: currentText.trim()
        });
      }

      // Construiește textul formatat cu vorbitori
      // Speaker 0 = Doctor (de obicei cel care vorbește primul/cel care pune întrebări)
      // Speaker 1 = Pacient
      textWithSpeakers = speakerSegments.map(segment => {
        const speakerLabel = segment.speaker === 0 ? 'DOCTOR' : 'PACIENT';
        return `[${speakerLabel}]: ${segment.text}`;
      }).join('\n\n');

      // Număr de vorbitori unici
      const uniqueSpeakers = new Set(alternative.words.map(w => w.speaker));
      speakerCount = uniqueSpeakers.size;
    }
  }

  // Fallback la format simplu dacă nu avem diarization
  if (!text && item.json.text) {
    text = item.json.text;
    textWithSpeakers = text; // Fără separare vorbitori
  }

  const textTrimmed = text.trim();
  const words = textTrimmed.split(/\s+/).filter(w => w.length > 0);
  const wordCount = words.length;
  const charCount = textTrimmed.length;

  // ============ LOGGING ============
  console.log('📝 ========== TRANSCRIERE PRIMITĂ ==========');
  console.log('📏 Lungime:', charCount, 'caractere');
  console.log('🔢 Cuvinte:', wordCount);
  console.log('👥 Vorbitori detectați:', speakerCount);
  console.log('⏱️ Durată audio:', item.json.metadata?.duration || 'necunoscut', 'secunde');
  console.log('📄 Preview cu vorbitori (primele 400 caractere):');
  console.log(textWithSpeakers.substring(0, 400) + (textWithSpeakers.length > 400 ? '...' : ''));
  console.log('==========================================');

  // ============ VALIDARE CRITICĂ ============
  if (charCount === 0) {
    item.json.transcription_metadata = {
      error: 'TRANSCRIERE GOALĂ',
      char_count: 0,
      word_count: 0,
      speaker_count: 0,
      is_valid: false
    };
    console.log('❌ TRANSCRIERE GOALĂ - item marcat ca invalid');
    continue;
  }

  if (charCount < 10) {
    item.json.transcription_metadata = {
      error: 'TRANSCRIERE PREA SCURTĂ',
      char_count: charCount,
      word_count: wordCount,
      speaker_count: speakerCount,
      is_valid: false,
      warning: 'Audio recepționat dar Whisper nu a putut transcrie suficient'
    };
    console.log('⚠️ TRANSCRIERE PREA SCURTĂ (' + charCount + ' caractere)');
    continue;
  }

  // ============ VALIDARE DIARIZATION ============
  if (speakerCount < 2) {
    console.log('⚠️ ATENȚIE: Doar ' + speakerCount + ' vorbitor detectat - verifică dacă diarization este activat!');
  }

  // ============ CATEGORII CONSULTAȚIE ============
  let consultationType = '';
  let completeness = 0;
  let warnings = [];

  if (charCount < 50) {
    consultationType = 'fragment';
    completeness = 10;
    warnings.push('⚠️ Fragment extrem de scurt - doar câteva cuvinte');
    warnings.push('📋 SOAP va fi incomplet sau inexistent');
  } else if (charCount < 200) {
    consultationType = 'scurtă';
    completeness = 30;
    warnings.push('⚠️ Consultație foarte scurtă (< 200 caractere)');
    warnings.push('📋 SOAP va fi parțial - probabil lipsesc examinare, diagnostic complet sau plan');
  } else if (charCount < 500) {
    consultationType = 'medie';
    completeness = 60;
    warnings.push('ℹ️ Consultație de lungime medie');
    warnings.push('📋 SOAP ar trebui să fie OK dacă consultația include toate etapele');
  } else if (charCount < 1000) {
    consultationType = 'completă';
    completeness = 85;
    warnings.push('✅ Consultație completă - lungime bună');
  } else {
    consultationType = 'detaliată';
    completeness = 100;
    warnings.push('✅ Consultație foarte detaliată');
  }

  // ============ DETECTARE TERMENI MEDICALI ============
  const medicalTermsFound = [];
  const medicalKeywords = [
    'simptom', 'durere', 'febr', 'temperatur', 'tensiune', 'puls',
    'diagnostic', 'tratament', 'medicament', 'rețet', 'prescri',
    'investigație', 'analiză', 'consult', 'examin', 'palp', 'auscult',
    'hipertensiune', 'diabet', 'infecție', 'inflamație', 'acut', 'cronic',
    'miligram', 'comprimate', 'capsule', 'ziua', 'zile'
  ];

  const lowerText = textTrimmed.toLowerCase();
  medicalKeywords.forEach(keyword => {
    if (lowerText.includes(keyword)) {
      medicalTermsFound.push(keyword);
    }
  });

  // ============ ESTIMARE CALITATE ============
  let qualityScore = 0;
  let qualityLabel = '';

  // Scoring
  if (wordCount >= 50) qualityScore += 20;
  if (wordCount >= 100) qualityScore += 20;
  if (medicalTermsFound.length >= 3) qualityScore += 20;
  if (medicalTermsFound.length >= 6) qualityScore += 20;
  if (speakerCount >= 2) qualityScore += 20; // Bonus pentru diarization

  if (qualityScore >= 80) qualityLabel = 'Excelent';
  else if (qualityScore >= 60) qualityLabel = 'Bun';
  else if (qualityScore >= 40) qualityLabel = 'Acceptabil';
  else qualityLabel = 'Slab';

  // ============ ÎMBOGĂȚIRE METADATA ============
  item.json.transcription_metadata = {
    // Statistici de bază
    char_count: charCount,
    word_count: wordCount,
    sentence_count: (textTrimmed.match(/[.!?]+/g) || []).length,
    speaker_count: speakerCount,
    has_diarization: speakerCount >= 2,

    // Clasificare
    consultation_type: consultationType,
    completeness_percent: completeness,
    quality_score: qualityScore,
    quality_label: qualityLabel,

    // Detectare conținut
    medical_terms_found: medicalTermsFound,
    medical_terms_count: medicalTermsFound.length,

    // Flags
    is_valid: true,
    is_complete_enough: charCount >= 200,
    has_medical_context: medicalTermsFound.length >= 3,

    // Warnings
    warnings: warnings,

    // Timestamp
    processed_at: new Date().toISOString()
  };

  // ============ SALVARE TEXT DUBLU FORMAT ============
  item.json.transcript = textTrimmed; // Text simplu
  item.json.transcript_with_speakers = textWithSpeakers; // Text cu [DOCTOR]/[PACIENT]
  item.json.speaker_count = speakerCount;
  item.json.speaker_segments = speakerSegments; // Array cu segmente pentru procesare avansată

  // ============ LOG METADATA ============
  console.log('📊 ========== METADATA GENERATĂ ==========');
  console.log('👥 Vorbitori:', speakerCount);
  console.log('🏷️ Tip consultație:', consultationType);
  console.log('📈 Completitudine:', completeness + '%');
  console.log('⭐ Calitate:', qualityLabel, '(' + qualityScore + '/100)');
  console.log('🏥 Termeni medicali găsiți:', medicalTermsFound.length);
  if (medicalTermsFound.length > 0) {
    console.log('   →', medicalTermsFound.slice(0, 10).join(', '));
  }
  if (warnings.length > 0) {
    console.log('⚠️ Warnings:');
    warnings.forEach(w => console.log('   ' + w));
  }
  console.log('==========================================');

  // ============ BACKWARD COMPATIBILITY ============
  item.json.transcription_length = charCount;
  item.json.transcription_words = wordCount;
  item.json.text = textTrimmed;
}

return items;

parameters.inputSchema:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "RaportConsultatieMedicala",
  "type": "object",
  "properties": {
    "rezumat": {
      "type": "string",
      "description": "Rezumă consultația în 2-3 propoziții clare pentru pacient, incluzând simptomele principale și planul general."
    },
    "raportSOAP": {
      "type": "object",
      "description": "Raportul medical structurat în format SOAP.",
      "properties": {
        "Subiectiv": {
          "type": "string",
          "description": "Ce spune PACIENTUL despre simptome, istoric, durată, context etc."
        },
        "Obiectiv": {
          "type": "string",
          "description": "Observațiile/examinările descrise de DOCTOR sau '[INFORMAȚIE LIPSĂ]'."
        },
        "Analiza": {
          "type": "string",
          "description": "Diagnosticul/evaluarea formulată de DOCTOR sau '[INFORMAȚIE LIPSĂ]'."
        },
        "Plan": {
          "type": "string",
          "description": "Planul de tratament/investigații menționat de DOCTOR sau '[INFORMAȚIE LIPSĂ]'."
        }
      },
      "required": ["Subiectiv", "Obiectiv", "Analiza", "Plan"]
    },
    "diagnosticePosibile": {
      "type": "array",
      "description": "Listă cu posibile diagnostice menționate sau deduse din conversație.",
      "items": {
        "type": "string"
      }
    },
    "coduriICD10Sugerate": {
      "type": "array",
      "description": "Listă de string-uri cu coduri ICD-10 sugerate pe baza Analizei (ex: ['J06.9', 'R51']). Lista goală dacă nu se identifică.",
      "items": {
        "type": "string"
      }
    },
    "pasiUrmatori": {
      "type": "array",
      "description": "Listă clară de acțiuni viitoare menționate de DOCTOR (ex: 'Analize de urină', 'Trimitere cardiologie').",
      "items": {
        "type": "string"
      }
    },
    "reteta": {
      "type": "object",
      "description": "Detalii despre medicamentele prescrise.",
      "properties": {
        "medicatie": {
          "type": "array",
          "description": "Listă de medicamente prescrise explicit de DOCTOR (ex: ['Paracetamol 500mg']). Lista goală dacă nu se prescrie nimic.",
          "items": {
            "type": "string"
          }
        },
        "instructiuni": {
          "type": "string",
          "description": "Instrucțiunile de administrare menționate de DOCTOR pentru medicamentele prescrise."
        },
        "numeDoctor": {
          "type": "string",
          "description": "Numele doctorului dacă este menționat în conversație."
        }
      },
      "required": ["medicatie", "instructiuni", "numeDoctor"]
    },
    "alerteMedicale": {
      "type": "array",
      "description": "Listă de string-uri cu potențiale alergii identificate din conversație ȘI interacțiunile medicamentoase validate de unelte. Lista goală dacă nu se identifică nimic.",
      "items": {
        "type": "string"
      }
    }
  },
  "required": [
    "rezumat",
    "raportSOAP",
    "diagnosticePosibile",
    "coduriICD10Sugerate",
    "pasiUrmatori",
    "reteta",
    "alerteMedicale"
  ]
}
